import React from 'react';
import { Link, useLocation } from 'react-router-dom';

function BottomNav({ role }) {
  const location = useLocation();
  const isCustomer = role === 'customer';
  const basePath = isCustomer ? '/dashboard-customer' : '/dashboard-worker';

  const navItems = [
    { icon: '🏠', label: 'Home', path: basePath },
    { icon: '📋', label: 'Orders', path: '/order-status' },
    { icon: '💬', label: 'Chat', path: '/inbox' },
    { icon: '💳', label: 'Wallet', path: '/wallet' },
    { icon: '👤', label: 'Profile', path: '/worker-profile' },
  ];

  return (
    <div style={{
      position: 'fixed',
      bottom: 0,
      left: '50%',
      transform: 'translateX(-50%)',
      maxWidth: '402px',
      width: '100%',
      background: 'white',
      display: 'flex',
      justifyContent: 'space-around',
      padding: '10px 0 16px',
      borderTop: '1px solid #E2E8F0',
      zIndex: 100
    }}>
      {navItems.map((item, i) => (
        <Link
          key={i}
          to={item.path}
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: '2px',
            fontSize: '20px',
            color: location.pathname === item.path ? '#0D9488' : '#94A3B8',
            textDecoration: 'none'
          }}
        >
          <span>{item.icon}</span>
          <span style={{ fontSize: '10px' }}>{item.label}</span>
        </Link>
      ))}
    </div>
  );
}

export default BottomNav;
